import { test } from 'node:test';
import assert from 'node:assert/strict';
import { ordenarNumeros, inverterLista } from './solution.mjs';

test('ordena números de verdade, do menor para o maior', () => {
  assert.deepEqual(ordenarNumeros([10, 2, 1, 20]), [1, 2, 10, 20]);
});

test('não altera a lista original', () => {
  const original = [3, 1, 2];
  assert.deepEqual(ordenarNumeros(original), [1, 2, 3]);
  assert.deepEqual(original, [3, 1, 2]);
});

test('inverte a ordem sem alterar a original', () => {
  const original = [1, 2, 3];
  assert.deepEqual(inverterLista(original), [3, 2, 1]);
  assert.deepEqual(original, [1, 2, 3]);
});

test('recusa valor que não é lista', () => {
  assert.throws(() => ordenarNumeros('1,2'));
});

solutionCode:
export function ordenarNumeros(lista) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.slice().sort((a, b) => a - b);
}

export function inverterLista(lista) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.slice().reverse();
}
